+
+      .checkbox-copy {
+        display: grid;
+        gap: 0.35rem;
+      }
+
+      label {
+        font-weight: 600;
+        line-height: 1.35;
+      }
+
+      .required {
+        color: var(--accent-strong);
+        font-weight: 700;
+      }
+
+      .helper {
+        margin: 0;
+        color: var(--muted);
+        line-height: 1.45;
+        font-size: 0.95rem;
+      }
+
+      .actions {
+        display: flex;
+        justify-content: flex-end;
+      }
+
+      button {
+        appearance: none;
+        border: 1px solid var(--border-strong);
+        border-radius: 0.9rem;
+        padding: 0.85rem 1.2rem;
+        background: linear-gradient(180deg, #24345c 0%, #1a2746 100%);
+        color: var(--text);
+        font: inherit;
+        font-weight: 700;
+        cursor: pointer;
+        min-width: 8.5rem;
