      .page {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 2rem 1rem;
      }

      .card {
        width: min(100%, 28rem);
        padding: 2rem;
        border: 1px solid var(--border);
        border-radius: 1.5rem;
        background: linear-gradient(180deg, var(--bg-elevated) 0%, var(--bg-panel) 100%);
        box-shadow: var(--shadow);
      }

      h1 {
        margin: 0 0 0.75rem;
        font-size: clamp(1.6rem, 4vw, 2rem);
        line-height: 1.15;
      }

      .lede {
        margin: 0 0 1.5rem;
        color: var(--muted);
        line-height: 1.5;
      }

      form {
        display: grid;
        gap: 1.25rem;
      }

      .form-field {
        padding: 1rem;
        border: 1px solid var(--border);
        border-radius: 1rem;
        background: rgba(255, 255, 255, 0.02);
      }

      .checkbox-row {
        display: flex;
        gap: 0.75rem;
        align-items: flex-start;
      }

      .checkbox-row input {
        width: 1.125rem;
        height: 1.125rem;
        margin-top: 0.2rem;
        accent-color: var(--accent);
      }

      .checkbox-copy {
        display: grid;
        gap: 0.35rem;
      }

      label {
        font-weight: 600;
        line-height: 1.35;
      }

      .required {
        color: var(--accent-strong);
        font-weight: 700;
      }

      .helper {
        margin: 0;
        color: var(--muted);
        line-height: 1.45;
        font-size: 0.95rem;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
      }

      button {
        appearance: none;
        border: 1px solid var(--border-strong);
        border-radius: 0.9rem;
        padding: 0.85rem 1.2rem;
