          }
        }
        for (const child of children) {
          el.append(child.nodeType ? child : document.createTextNode(child));
        }
        return el;
      };

      function ConsentField() {
        const checkboxId = "terms-consent";
        const helperId = "terms-consent-help";

        return h("div", { className: "form-field" }, [
          h("div", { className: "checkbox-row" }, [
            h("input", {
              id: checkboxId,
              name: "consent",
              type: "checkbox",
              required: true,
              "aria-describedby": helperId,
            }),
            h("div", { className: "checkbox-copy" }, [
              h("label", { htmlFor: checkboxId }, [
                "I agree to the terms of use ",
                h("span", { className: "required", textContent: "*" }),
              ]),
              h("p", {
                className: "helper",
                id: helperId,
                textContent: "Required to continue.",
              }),
            ]),
          ]),
        ]);
      }

      function App() {
        const main = h("main", { id: "main-content", className: "page" }, [
